449		// 已失效，必须拒绝；交付为空，不携带包内容、摘要、记录标识或交换状态。
450		f.clk.t = f.end.Add(-time.Minute)
451		del, err := fetchWhileStoreBusy(f.s, f.clk, f.end, rcv, x.ID)
452		if !errors.Is(err, ErrAccessDenied) {
453			t.Fatalf("binding expired during wait: err = %v, want ErrAccessDenied", err)
454		}
455		if !emptyDelivery(del) {
456			t.Fatalf("denied delivery must carry no exchange info: %+v", del)
457		}
458	
459		// 核对发生在截止前一刻（仍有等待）：其他条件满足，取包成功，
460		// 返回创建时固化的包与摘要、当前状态。
461		f.clk.t = f.end.Add(-2 * time.Minute)
462		del, err = fetchWhileStoreBusy(f.s, f.clk, f.end.Add(-time.Nanosecond), rcv, x.ID)
463		if err != nil {
464			t.Fatalf("check just before expiry must succeed: %v", err)
465		}
466		if del.ExchangeID != x.ID || del.Digest != x.Digest || del.Status != ExchangePending {
467			t.Fatalf("bad delivery: %+v", del)
468		}
469		if len(del.Package.Records) != 2 {
470			t.Fatalf("delivery records = %d, want 2", len(del.Package.Records))
471		}
472	
473		// 没有等待的正常取包同样遵守半开边界：恰好截止时刻失效，
474		// 截止前一纳秒仍可取，边界语义与 Read 完全一致。
475		f.clk.t = f.end
476		if del, err := f.s.FetchPackage(rcv, x.ID); !errors.Is(err, ErrAccessDenied) {
477			t.Fatalf("fetch exactly at expiry: err = %v, want ErrAccessDenied, delivery = %+v", err, del)
478		}
479		f.clk.t = f.end.Add(-time.Nanosecond)
480		if _, err := f.s.FetchPackage(rcv, x.ID); err != nil {
481			t.Fatalf("fetch just before expiry: %v", err)
482		}
483	}
