485	// fetchWhileStoreBusyLocked 在已持有存储锁的前提下发起取包，等待 goroutine
486	// 阻塞在锁上后执行 mutate（直接改动内存快照）再放行：用于模拟“请求先发出、
487	// 其他操作先完成、本次核对随后才开始”的排队场景。
488	func fetchWhileStoreBusyLocked(s *Store, mutate func(snap *snapshot, now time.Time), actor Actor, exchangeID ID) (PackageDelivery, error) {
489		done := make(chan struct {
490			del PackageDelivery
491			err error
492		}, 1)
493		go func() {
494			del, err := s.FetchPackage(actor, exchangeID)
495			done <- struct {
496				del PackageDelivery
497				err error
498			}{del, err}
499		}()
500		// 给取包 goroutine 留出进入 FetchPackage 并阻塞在锁上的时间，确保请求
501		// 是在下面的状态改动之前发出的。
502		time.Sleep(50 * time.Millisecond)
503		mutate(s.data, s.now())
504		s.mu.Unlock()
505		o := <-done
506		return o.del, o.err
507	}
