		t.Fatalf("bad digest err = %v", err)
	}
	// 其他接收方、内部使用者、不存在的交换不能代交。
	if _, err := f.s.SubmitReceipt(rcvB, x.ID, x.Digest, ReceiptAccepted, ""); !errors.Is(err, ErrAccessDenied) {
		t.Fatalf("other receiver err = %v", err)
	}
