func TestInternalExchangeQueries(t *testing.T) {
	f := setupExchange(t)
	xs1, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "req-q1")
	if err != nil {
