// grantOtherCoveringSameRecords 再建一条同患者、同接收方、覆盖同样两条记录的
// 整类授权，用于验证绑定授权到期时不会自动改用它。
func grantOtherCoveringSameRecords(t *testing.T, f *createExchangeTimingFixture, start, end time.Time) ID {
