// clock 返回夹具存储使用的可控时钟。
func (f *createExchangeTimingFixture) clock() *fakeClock {
	// newTestStore 内部构造时钟；这里从同包测试直接读取存储时钟不可得，
	// 因此 setup 时一并保存。
	return f.clk
}

// createExchangeWhileStoreBusy 模拟创建请求发出后被同一存储上的其他操作阻塞：
// 先占用存储互斥锁，待创建 goroutine 发出请求并阻塞后，把时钟推进到 advanceTo
// （即“等待结束、真正开始核对本次授权”的时刻），再放行。返回创建结果与错误。
func createExchangeWhileStoreBusy(f *createExchangeTimingFixture, advanceTo time.Time, authID ID, req string) (Exchange, error) {
	f.s.mu.Lock()
	type outcome struct {
		x   Exchange
		err error
	}
	done := make(chan outcome, 1)
	go func() {
		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, authID, []ID{f.diag, f.ord}, req)
		done <- outcome{x, err}
	}()
	// 给创建 goroutine 留出进入 CreateExchange 并阻塞在锁上的时间，确保请求
	// 是在时钟推进之前发出的——核对只能采用 advanceTo 这一时刻。
	time.Sleep(50 * time.Millisecond)
	setFakeClock(f.s, advanceTo)
	f.s.mu.Unlock()
	o := <-done
	return o.x, o.err
}

// setFakeClock 把存储当前注入时钟的时刻改写为 t（测试包内可控时钟）。
func setFakeClock(s *Store, t time.Time) {
	s.clock = func() time.Time { return t }
}

// fakeClockAt 直接把测试夹具的时钟时刻设置为 t。夹具的时钟由 newTestStore
// 创建，测试通过存储重新注入同一时刻即可。
func (f *createExchangeTimingFixture) setClock(t time.Time) {
	setFakeClock(f.s, t)
}

